from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    stack = []
    temp = ''
    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if stack:
                stack.pop()
                if stack:
                    temp += char
                else:
                    result.append(temp + char)
                    temp = ''
            else:
                temp += char
    if stack:
        raise ValueError("Unbalanced parentheses")
    return result
```

