import math

def triangle_area(a, b, c):
    sides = sorted([a, b, c])
    if sides[0] + sides[1] > sides[2]:
        s = (sides[0] + sides[1] + sides[2]) / 2
        return round(math.sqrt(s * (s - sides[0]) * (s - sides[1]) * (s - sides[2])), 2)
    else:
        return -1
```

