def hex_key(num):
    hex_dict = {str(i): str(i) for i in range(10)}
    hex_dict.update({chr(i): chr(i) for i in range(ord('A'), ord('F') + 1)})
    prime_hex = {'2': '2', '3': '3', '5': '5', '7': '7', 'B': 'B', 'D': 'D'}
    count = 0
    for i in num:
        if i in prime_hex:
            count += 1
    return count
```
