```python
def encrypt(s):
    result = ""
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    for char in s:
        if char.isalpha():
            shift = 2 * 2
            index = alphabet.index(char.lower())
            if char.isupper():
                result += alphabet[(index + shift) % 26].upper()
            else:
                result += alphabet[(index + shift) % 26]
        else:
            result += char
    return result
```

